<template><view :class="['app-page',{dark}]"><ui-header title="提现申请" back/><view class="amount-card"><view class="amount-head"><ui-icon name="coins" :size="44"/><text>可提现</text></view><text class="price big">¥{{balance.toFixed(2)}}</text><view class="amount-links"><view @tap="goDetail"><text>消费明细</text><ui-icon name="chevron-right" :size="24"/></view><view @tap="goRecords"><text>提现记录</text><ui-icon name="chevron-right" :size="24"/></view><view @tap="showRules=true"><text>规则说明</text><ui-icon name="chevron-right" :size="24"/></view></view></view><view class="withdraw-card"><view class="withdraw-head"><text class="section-title">申请提现</text><text @tap="amount=String(balance)">全部</text></view><input v-model="amount" type="digit" placeholder="请输入提现金额"/><text class="section-title method-title">处理方式</text><view class="method"><view class="wechat"><ui-icon name="wallet" :size="34"/></view><text>平台人工审核打款</text><view class="selected"><ui-icon name="check" :size="24"/></view></view></view><text v-if="error" class="error">{{error}}</text><view class="primary-btn confirm" @tap="confirm">提交审核</view><ui-modal :show="showRules" title="提现规则" :content="ruleCopy" confirm-text="知道了" @confirm="showRules=false" @cancel="showRules=false"/></view></template>
<script>import{isDark}from'@/utils/app';import{api}from'@/services/api';export default{data(){return{dark:false,balance:0,amount:'',error:'',submitting:false,showRules:false,ruleCopy:'1. 收益到账后可能存在冻结期，冻结结束后转入可提现账户。\n\n2. 提现由平台审核并人工打款，完成后可查看记录；充值余额不计入打手收益。\n\n3. 审核结果会写入钱包流水。'}},onLoad(){this.dark=isDark();api.getWallet().then(data=>{this.balance=Number(data.withdrawable||0)}).catch(e=>{this.error=e.message||'提现余额加载失败，请重新进入'})},methods:{goDetail(){uni.navigateTo({url:'/pages/wallet/detail'})},goRecords(){uni.navigateTo({url:'/pages/wallet/withdrawals'})},async confirm(){const value=Number(this.amount);if(this.submitting)return;if(!value||value<=0||value>this.balance){this.error='请输入不大于可提现余额的金额';return}this.submitting=true;try{await api.withdraw(value);uni.redirectTo({url:'/pages/wallet/withdrawals'})}catch(e){this.error=e.message||'提交失败'}finally{this.submitting=false}}}}</script>
<style scoped>.amount-card{margin:24rpx 28rpx;padding:30rpx;border-radius:26rpx;background:linear-gradient(120deg,#fff0c7,#ffdca0);box-shadow:0 14rpx 34rpx rgba(211,145,37,.12)}.amount-head{display:flex;align-items:center;gap:12rpx}.big{display:block;margin:16rpx 0;font-size:46rpx}.amount-links{display:flex;gap:36rpx;font-size:23rpx}.amount-links>view{display:flex;align-items:center}.withdraw-card{margin:24rpx 28rpx;padding:28rpx;border-radius:24rpx;background:var(--surface);box-shadow:var(--shadow-card)}.withdraw-head{display:flex;justify-content:space-between}.withdraw-card input{height:82rpx;margin:20rpx 0;border:1rpx solid var(--line);border-radius:16rpx;padding:0 20rpx;color:var(--text)}.method-title{display:block;margin:28rpx 0}.method{display:flex;align-items:center;gap:14rpx}.wechat{width:50rpx;height:50rpx;display:flex;align-items:center;justify-content:center;border-radius:16rpx;background:#e8f9ef}.selected{margin-left:auto;width:36rpx;height:36rpx;display:flex;align-items:center;justify-content:center;border-radius:50%;background:var(--primary)}.error{display:block;margin:10rpx 56rpx;color:var(--primary);font-size:23rpx}.confirm{margin:36rpx 78rpx}</style>
